'use strict';
const characterViewNames={front:'Front',side:'Side',back:'Back'};
let viewEditorContext=null,viewDialogActor=null;
function rigArtwork(o){return Object.fromEntries(['name','imageSrc','originalImageSrc','imageWidth','imageHeight','parts','rigNeutral','mouth','face','rigGuide'].filter(k=>o[k]!==undefined).map(k=>[k,structuredClone(o[k])]))}
function characterViewAt(o,t=time){return(o.viewKeys||[]).filter(k=>k.t<=t+.00001).sort((a,b)=>a.t-b.t).at(-1)?.view||'front'}
function characterAtView(o,t=time){if(o.type!=='puppet'||!o.characterViews)return o;const art=o.characterViews[characterViewAt(o,t)];if(!art)return o;return{...o,...art,name:o.name,height:o.width*art.imageHeight/art.imageWidth,characterViews:undefined}}
function normalizeViewArtwork(o,data){const art=rigArtwork(data),roles=new Set();for(const p of art.parts){if(p.role!=='other'&&roles.has(p.role))throw Error('Use one part for each named body role in a character view.');roles.add(p.role)}const canonical=o.characterViews?.front||rigArtwork(o),ids=new Map();for(const part of canonical.parts)if(part.role!=='other'&&!art.parts.some(p=>p.role===part.role&&p.channel===part.channel))throw Error('Add the '+rigRoles[part.role][0].toLowerCase()+' with its matching joint control to this view.');for(const part of art.parts){const match=canonical.parts.find(p=>p.role===part.role&&p.role!=='other');ids.set(part.id,match?.id||part.id)}for(const part of art.parts){part.id=ids.get(part.id);part.parentId=ids.get(part.parentId)||null}if(art.mouth)art.mouth.parentId=ids.get(art.mouth.parentId)||null;for(const r of Object.values(art.face?.regions||{}))if(r.parentId)r.parentId=ids.get(r.parentId)||null;const candidate={...o,...art,characterViews:undefined};if(!validPuppet(candidate))throw Error('Check this view’s cut-outs, joints and mouth area.');return art}
function attachCharacterView(o,view,data){if(o.type!=='puppet'||o.locked)throw Error('Choose an unlocked picture character.');if(!Object.hasOwn(characterViewNames,view))throw Error('Choose front, side or back.');const art=normalizeViewArtwork(o,data);o.characterViews??={front:rigArtwork(o)};o.characterViews[view]=art;if(view==='front')Object.assign(o,structuredClone(art),{name:o.name});return art}
function keyCharacterView(o,view,at=time){if(o.type!=='puppet'||o.locked||!o.characterViews?.[view])throw Error('Prepare this character view first.');if(!Number.isFinite(at)||at<clipStart(o)||at>clipEnd(o))throw Error('Keep view changes inside the character clip.');const keys=o.viewKeys??=[];if(keys.length>=200&&!keys.some(k=>Math.abs(k.t-at)<.015))throw Error('Keep up to 200 view changes.');const k=keys.find(k=>Math.abs(k.t-at)<.015);if(k)k.view=view;else keys.push({t:Math.round(at*1000)/1000,view});keys.sort((a,b)=>a.t-b.t);save();render()}
const stateBeforeViews=stateAt;stateAt=function(o,t){const oldTime=time;time=t;try{return stateBeforeViews(characterAtView(o,t),t)}finally{time=oldTime}};
const availableBeforeViews=bodyFieldAvailable;bodyFieldAvailable=function(o,field){return availableBeforeViews(characterAtView(o),field)};
const matricesBeforeViews=puppetMatrices;puppetMatrices=function(o,v){return matricesBeforeViews(characterAtView(o),v)};
const paintBeforeViews=paintPuppet;paintPuppet=function(c,o,v,t=time){return paintBeforeViews(c,characterAtView(o,t),v,t)};
const boundsBeforeViews=bounds;bounds=function(o,v){return boundsBeforeViews(characterAtView(o),v)};
const handlesBeforeViews=poseHandles;poseHandles=function(o){return handlesBeforeViews(characterAtView(o))};
const ikBeforeViews=puppetIK;puppetIK=function(o,key,target,v){return ikBeforeViews(characterAtView(o),key,target,v)};
const handBeforeViews=interactionHand;interactionHand=function(o,v,side){return handBeforeViews(characterAtView(o),v,side)};
const solveHandBeforeViews=solveInteractionHand;solveInteractionHand=function(o,v,side,target){return solveHandBeforeViews(characterAtView(o),v,side,target)};
const jointBeforeViews=poseJoint;poseJoint=function(o,key,p,initial,keyBase){if(!o.characterViews)return jointBeforeViews(o,key,p,initial,keyBase);const viewed=characterAtView(o);jointBeforeViews(viewed,key,p,initial,keyBase);o.keys=viewed.keys;if(viewed.bodyAnimation)o.bodyAnimation=viewed.bodyAnimation};
const sourcesBeforeViews=preloadProductionAssets;preloadProductionAssets=async function(s){await sourcesBeforeViews(s);await Promise.all(s.objects.flatMap(o=>Object.values(o.characterViews||{}).flatMap(v=>[v.imageSrc,...v.parts.map(p=>p.src),...Object.values(v.mouth?.sprites||{}),...puppetFaceSources(v)])).filter(Boolean).map(imageReady))};
const exportBeforeViews=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{for(const s of project.scenes)await preloadProductionAssets(s);return exportBeforeViews()};
const thumbnailBeforeViews=renderStoryThumbnail;renderStoryThumbnail=async function(c,s){await preloadProductionAssets(s);return thumbnailBeforeViews(c,s)};
const continueBeforeViews=continuitySnapshot;continuitySnapshot=function(o,s,at){const copy=continueBeforeViews(o,s,at);if(o.type==='puppet'&&o.characterViews)copy.viewKeys=[{t:0,view:characterViewAt(o,at)}];return copy};
const moveBeforeViews=moveVisual;moveVisual=function(o,change){const start=clipStart(o);moveBeforeViews(o,change);const delta=clipStart(o)-start;if(change.mode==='move'&&delta)for(const k of o.viewKeys||[])k.t=clamp(k.t+delta,0,current().duration)};
const durationBeforeViews=changeSceneDuration;changeSceneDuration=function(s,n){if(s.objects.some(o=>o.viewKeys?.some(k=>k.t>+n+.001)))return toast('Move character view keys before shortening the scene.'),false;return durationBeforeViews(s,n)};
document.body.insertAdjacentHTML('beforeend','<dialog id="characterViewsDialog"><div class="tool-heading"><h2>Character views</h2><button id="closeCharacterViews">Done</button></div><p class="note">Prepare front, side and back artwork in the cut-out editor. Reuse the same named body roles. View changes keep this character’s pose keys, voice and object links. Views are supplied artwork, not generated 3D turns.</p><div id="characterViewCards" class="ease-card-list"></div><div id="characterViewKeys" class="ease-card-list"></div><p id="characterViewStatus" role="status" class="note"></p></dialog>');
function viewActor(){return current().objects.find(o=>o.id===viewDialogActor)}
function renderCharacterViews(){const o=viewActor();if(!o)return;const list=$('characterViewCards');list.replaceChildren();for(const [view,name]of Object.entries(characterViewNames)){const row=document.createElement('article');row.className='ease-entry';const label=document.createElement('strong');label.textContent=name+(characterViewAt(o)===view?' · current':'');const prepared=view==='front'||!!o.characterViews?.[view];row.append(label,storyButton(prepared?'Edit artwork':'Prepare artwork',()=>editCharacterView(o,view)),storyButton('Use here',()=>{try{if(!o.characterViews)attachCharacterView(o,'front',o);keyCharacterView(o,view);renderCharacterViews()}catch(e){toast(e.message)}}));row.lastElementChild.disabled=!prepared||o.locked;list.append(row)}const keys=$('characterViewKeys');keys.replaceChildren();for(const k of o.viewKeys||[]){const row=document.createElement('div');row.className='ease-entry';const text=document.createElement('span');text.textContent=k.t.toFixed(2)+'s · '+characterViewNames[k.view];row.append(text,storyButton('Go',()=>{time=k.t;draw();renderCharacterViews()}),storyButton('Remove',()=>{if(o.locked)return;o.viewKeys=o.viewKeys.filter(a=>a!==k);save();render();renderCharacterViews()}));keys.append(row)}$('characterViewStatus').textContent='Playhead: '+time.toFixed(2)+'s. A view remains active until the next view key.'}
function openCharacterViews(o=object()){if(o?.type!=='puppet'||o.locked)return toast('Select an unlocked picture character.');stop();viewDialogActor=o.id;renderCharacterViews();$('characterViewsDialog').showModal()}
function editCharacterView(o,view){$('characterViewsDialog').close();const data=o.characterViews?.[view]||(view==='front'?rigArtwork(o):{name:o.name+' · '+view,imageSrc:'',imageWidth:o.imageWidth,imageHeight:o.imageHeight,parts:[],rigNeutral:structuredClone(o.rigNeutral||{...pose,...rigDefaults}),mouth:null});openImageRig({...o,...structuredClone(data),characterViews:undefined,viewKeys:undefined});viewEditorContext={project,sceneId:current().id,actorId:o.id,view};$('saveImageRig').textContent='Save '+characterViewNames[view].toLowerCase()+' view';$('rigHint').textContent='Import and rig this view using the same body roles as the front. Voice and timeline links stay on the original character.'}
const saveRigBeforeViews=$('saveImageRig').onclick;$('saveImageRig').onclick=async()=>{if(!viewEditorContext){const actor=current().objects.find(o=>o.id===rigEditId);await saveRigBeforeViews();if(actor?.characterViews&&!$('imageRigDialog').open){actor.characterViews.front=rigArtwork(actor);save()}return}try{const context=viewEditorContext,o=current().objects.find(o=>o.id===context.actorId);if(project!==context.project||current().id!==context.sceneId||!o)throw Error('The character changed. Reopen its views.');const data=rigArtwork(imageRigDraft);attachCharacterView(o,context.view,data);save();render();$('imageRigDialog').close();openCharacterViews(o)}catch(e){toast(e.message)}};
$('imageRigDialog').addEventListener('close',()=>{viewEditorContext=null;$('saveImageRig').textContent='Save character & add'});$('closeCharacterViews').onclick=()=>$('characterViewsDialog').close();
const controlsBeforeViews=renderControls;renderControls=function(){controlsBeforeViews();if(object()?.type!=='puppet')return;const b=storyButton('Front, side & back views',()=>openCharacterViews());b.id='openCharacterViews';b.disabled=!!object().locked;$('editImageRig')?.after(b)};
const timelineBeforeViews=renderTimeline;renderTimeline=function(){timelineBeforeViews();if(timelineDrag)return;for(const o of current().objects)if(o.viewKeys?.length){const row=lane('Views · '+o.name,'character-view-track');for(const k of o.viewKeys){const b=storyButton('◆',()=>{stop();time=k.t;selectLayers([o.id]);render()});b.className='body-timeline-key';b.style.left=(sceneOffset()+k.t)*timelineZoom+'px';b.title=characterViewNames[k.view]+' · '+k.t.toFixed(2)+'s';row.area.append(b)}}};
function validRigGuide(g){return !g||Object.keys(g).length===Object.keys(guideLandmarks).length&&Object.entries(g).every(([id,p])=>Object.hasOwn(guideLandmarks,id)&&p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.abs(p.x)<=2000&&Math.abs(p.y)<=2000)}
const validatorBeforeViews=valid;function validAlternateArtwork(p,s,o,art){const flat={...o,...art,characterViews:undefined};return validatorBeforeViews({...p,scenes:p.scenes.map(scene=>scene===s?{...s,objects:s.objects.map(actor=>actor===o?flat:actor)}:scene)})}valid=function(p){try{return validatorBeforeViews(p)&&p.scenes.every(s=>s.objects.every(o=>validRigGuide(o.rigGuide)&&(!o.characterViews||o.type==='puppet'&&!!o.characterViews.front&&Object.entries(o.characterViews).every(([view,art])=>Object.hasOwn(characterViewNames,view)&&validRigGuide(art.rigGuide)&&validAlternateArtwork(p,s,o,art)&&art.parts.every(part=>!part.bend||typeof part.bend.enabled==='boolean'&&Number.isFinite(part.bend.zone)&&part.bend.zone>=.1&&part.bend.zone<=.9&&Number.isFinite(part.bend.strength)&&part.bend.strength>=0&&part.bend.strength<=1)))&&(!o.viewKeys||o.type==='puppet'&&Array.isArray(o.viewKeys)&&o.viewKeys.length<=200&&o.viewKeys.every(k=>Number.isFinite(k.t)&&k.t>=0&&k.t<=s.duration+.001&&!!o.characterViews?.[k.view]))))}catch{return false}};
